(205057, 11504, 472, '<td valign="top">love the multilayered feel of this shot.</td>', 'love the multilayered feel of this shot.', '2003-02-02 13:13:04.000000', NULL, 1),
(205058, 11663, 472, '<td valign="top">what an absolutely exquisite photo of an amazing setting</td>', 'what an absolutely exquisite photo of an amazing setting', '2003-02-02 13:13:35.000000', NULL, 1),
(205059, 11454, 1037, '<td valign="top">I always enjoy seeing that weird warped effect in office building reflecitons like this one. Well captured. The way there are just a few windows with light inside them is really nice.</td>', 'I always enjoy seeing that weird warped effect in office building reflecitons like this one. Well captured. The way there are just a few windows with light inside them is really nice.', '2003-02-02 13:14:03.000000', NULL, 1),
(205060, 11610, 472, '<td valign="top">i predict this shot will do very well.  i dont know if i like the lip of the cupola visible in the top of the frame tho ...</td>', 'i predict this shot will do very well.  i dont know if i like the lip of the cupola visible in the top of the frame tho ...', '2003-02-02 13:14:10.000000', NULL, 1),
(205061, 11618, 1037, '<td valign="top">Beautiful. I have to find out how people achieve these strong, gritty colours. There''s another photo I''ve seen in this challenge that has the same effect. This one looks like a water colour painting. 10 from me.</td>', 'Beautiful. I have to find out how people achieve these strong, gritty colours. There''s another photo I''ve seen in this challenge that has the same effect. This one looks like a water colour painting. 10 from me.', '2003-02-02 13:15:36.000000', NULL, 1),
(205062, 11453, 1037, '<td valign="top">Interesting house. The tight framing is a bit overwhelming though. Makes the photo too busy. Also, the shadows are very strong.</td>', 'Interesting house. The tight framing is a bit overwhelming though. Makes the photo too busy. Also, the shadows are very strong.', '2003-02-02 13:17:27.000000', NULL, 1),
(205063, 11523, 1037, '<td valign="top">Whoa, great camera angle! The textures and colours are lovely too... very warm and rustic.</td>', 'Whoa, great camera angle! The textures and colours are lovely too... very warm and rustic.', '2003-02-02 13:18:50.000000', NULL, 1),
(205065, 11363, 1037, '<td valign="top">Lovely composition, gorgeous black and white. This is just a beautiful photo. 10 from me.</td>', 'Lovely composition, gorgeous black and white. This is just a beautiful photo. 10 from me.', '2003-02-02 13:20:05.000000', NULL, 1),
(205066, 11666, 1037, '<td valign="top">I really like this. It''s simple, but striking. I like the gradients that run along the walls, from bright near the top to dark at the edges.</td>', 'I really like this. It''s simple, but striking. I like the gradients that run along the walls, from bright near the top to dark at the edges.', '2003-02-02 13:21:10.000000', NULL, 1),
(205071, 11458, 1037, '<td valign="top">I like the photo, but the puzzle filter seems a bit generic. It''s a fun effect, but it doesn''t tie into the image in any meaningful way.</td>', 'I like the photo, but the puzzle filter seems a bit generic. It''s a fun effect, but it doesn''t tie into the image in any meaningful way.', '2003-02-02 13:32:23.000000', NULL, 1),
(205072, 11496, 1037, '<td valign="top">Great colours and lovely framing of the arch. The wreath has a nice effect, offsetting the symmetry of the image as a whole. Nice photo.</td>', 'Great colours and lovely framing of the arch. The wreath has a nice effect, offsetting the symmetry of the image as a whole. Nice photo.', '2003-02-02 13:33:32.000000', NULL, 1),
(205074, 11645, 1037, '<td valign="top">Cool. Interesting lines and textures. Taking the negative of it emphasises those things nicely.</td>', 'Cool. Interesting lines and textures. Taking the negative of it emphasises those things nicely.', '2003-02-02 13:37:42.000000', NULL, 1),
(205075, 11433, 1037, '<td valign="top">Cool, I love the soft, diffuse light in this. The composition is just perfect, and the colours are gorgeous.</td>', 'Cool, I love the soft, diffuse light in this. The composition is just perfect, and the colours are gorgeous.', '2003-02-02 13:39:08.000000', NULL, 1),
(205076, 11443, 1037, '<td valign="top">Bright, colourful stained glass. The subdued colours of the surrounding walls, etc. sets that off well. It''s a little busy, however.</td>', 'Bright, colourful stained glass. The subdued colours of the surrounding walls, etc. sets that off well. It''s a little busy, however.', '2003-02-02 13:41:22.000000', NULL, 1),
(205077, 11483, 1037, '<td valign="top">Weird and spooky. I can''t imagine what must be behind there! That door handle is really interesting, I wish the bright light didn''t obscure it so much.</td>', 'Weird and spooky. I can''t imagine what must be behind there! That door handle is really interesting, I wish the bright light didn''t obscure it so much.', '2003-02-02 13:42:40.000000', NULL, 1),
(205078, 11387, 1037, '<td valign="top">There are a lot of photos similar to this one. The textures are great, and the high contrast sets them off nicely. The colours are a little washed out though.</td>', 'There are a lot of photos similar to this one. The textures are great, and the high contrast sets them off nicely. The colours are a little washed out though.', '2003-02-02 13:44:01.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(205080, 11416, 1037, '<td valign="top">The composition of this is interesting in an awkward way. The colours are a little washed out and the focus seems soft. I like the rivets and the reflections on the red metal.</td>', 'The composition of this is interesting in an awkward way. The colours are a little washed out and the focus seems soft. I like the rivets and the reflections on the red metal.', '2003-02-02 13:46:31.000000', NULL, 1),
(205082, 11594, 1037, '<td valign="top">This is such a charming photo, full of life and personality. I love what you captured here.</td>', 'This is such a charming photo, full of life and personality. I love what you captured here.', '2003-02-02 13:48:59.000000', NULL, 1),
(205084, 11505, 4411, '<td valign="top">Beautiful colours, and great composition. I especially like the coloured light cast onto the wall.</td>', 'Beautiful colours, and great composition. I especially like the coloured light cast onto the wall.', '2003-02-02 13:51:10.000000', NULL, 1),
(205086, 11610, 1037, '<td valign="top">Very grand. Are those stars always there at the top? Looks a bit.... odd. And what is that at the top edge of the photo? The composition is nice and the lighting is beautiful and diffuse.</td>', 'Very grand. Are those stars always there at the top? Looks a bit.... odd. And what is that at the top edge of the photo? The composition is nice and the lighting is beautiful and diffuse.', '2003-02-02 13:51:57.000000', NULL, 1),
(205087, 11433, 4411, '<td valign="top">Excellent shot. Has a very ''clean'' look that I like a lot.</td>', 'Excellent shot. Has a very ''clean'' look that I like a lot.', '2003-02-02 13:52:19.000000', NULL, 1),
(205089, 11513, 1037, '<td valign="top">Very interesting swirly patterns. I''m not quite sure what it adds to the image as a whole. The darkness of the foreground makes the photo a bit flat.</td>', 'Very interesting swirly patterns. I''m not quite sure what it adds to the image as a whole. The darkness of the foreground makes the photo a bit flat.', '2003-02-02 13:52:55.000000', NULL, 1),
(205090, 11661, 1037, '<td valign="top">Cool effect. I like the mood of this photo. Gritty and urban. The power lines have become a bit jaggy from resizing. Sometimes it can help to blur the photo by one or two pixels before you resize/resample it.</td>', 'Cool effect. I like the mood of this photo. Gritty and urban. The power lines have become a bit jaggy from resizing. Sometimes it can help to blur the photo by one or two pixels before you resize/resample it.', '2003-02-02 13:55:01.000000', NULL, 1),
(205091, 11489, 1037, '<td valign="top">Nice textures and composition. After voting on over half the photos now, though, I''ve seen a lot of windows like this one!</td>', 'Nice textures and composition. After voting on over half the photos now, though, I''ve seen a lot of windows like this one!', '2003-02-02 13:59:01.000000', NULL, 1),
(205093, 11488, 1037, '<td valign="top">Nice composition. I like the tinted black and white and the old, weatherbeaten wood.</td>', 'Nice composition. I like the tinted black and white and the old, weatherbeaten wood.', '2003-02-02 14:00:35.000000', NULL, 1),
(205095, 11383, 1037, '<td valign="top">Very cool composition. The dramatic lighting is an interesting effect. I like this photo a lot.</td>', 'Very cool composition. The dramatic lighting is an interesting effect. I like this photo a lot.', '2003-02-02 14:02:42.000000', NULL, 1),
(205097, 11537, 1037, '<td valign="top">Wow, I love the negative space effect. That wall has enough texture that it''s a pleasure to look at. The windows are a great shape.</td>', 'Wow, I love the negative space effect. That wall has enough texture that it''s a pleasure to look at. The windows are a great shape.', '2003-02-02 14:05:50.000000', NULL, 1),
(205098, 11636, 1037, '<td valign="top">Indeed! Lots of interesting shapes. I think the tonal depth of this photo could use some work though.</td>', 'Indeed! Lots of interesting shapes. I think the tonal depth of this photo could use some work though.', '2003-02-02 14:07:08.000000', NULL, 1),
(205099, 11635, 1037, '<td valign="top">Interesting. I like the rakish angle of this and the very simple grey on black tones.</td>', 'Interesting. I like the rakish angle of this and the very simple grey on black tones.', '2003-02-02 14:11:05.000000', NULL, 1),
(205101, 11663, 1037, '<td valign="top">Wow, beautiful. It sets up a very interesting little world, and invites you to travel through it. Nice black and white, and strong composition. 10 from me.</td>', 'Wow, beautiful. It sets up a very interesting little world, and invites you to travel through it. Nice black and white, and strong composition. 10 from me.', '2003-02-02 14:12:51.000000', NULL, 1),
(205102, 11445, 1037, '<td valign="top">Cool! Great perspective all along that wall and strong composition.</td>', 'Cool! Great perspective all along that wall and strong composition.', '2003-02-02 14:14:16.000000', NULL, 1),
(205103, 11510, 1037, '<td valign="top">Nice. I like the DOF on this that makes the lead glass window so soft and pretty.</td>', 'Nice. I like the DOF on this that makes the lead glass window so soft and pretty.', '2003-02-02 14:15:56.000000', NULL, 1),
(205105, 11524, 1037, '<td valign="top">Cool. It does have a dreamlike quality. I like the softness of this image.</td>', 'Cool. It does have a dreamlike quality. I like the softness of this image.', '2003-02-02 14:17:11.000000', NULL, 1),
(205106, 11461, 1037, '<td valign="top">Interesting. The colours are really nice. The lighting is kind of strange.</td>', 'Interesting. The colours are really nice. The lighting is kind of strange.', '2003-02-02 14:18:03.000000', NULL, 1),
(205107, 11505, 1037, '<td valign="top">Very pretty and strong composition. It''s hard to imagine how this photo could be any better!</td>', 'Very pretty and strong composition. It''s hard to imagine how this photo could be any better!', '2003-02-02 14:20:12.000000', NULL, 1),
(205108, 11577, 1037, '<td valign="top">Very experimental. It seems a bit mystical or spritual. The washed out look isn''t very appealing to me though.</td>', 'Very experimental. It seems a bit mystical or spritual. The washed out look isn''t very appealing to me though.', '2003-02-02 14:21:37.000000', NULL, 1),
(205109, 11612, 1037, '<td valign="top">Cool. The overlay makes me think about the history of those windows, and what might have happened inside the building over time. Very nice work.</td>', 'Cool. The overlay makes me think about the history of those windows, and what might have happened inside the building over time. Very nice work.', '2003-02-02 14:22:52.000000', NULL, 1),
(205110, 11482, 1037, '<td valign="top">I love it! Great work. It''s getting very late at night where I am, so I''m too tired to elaborate, but I''m giving this 10!</td>', 'I love it! Great work. It''s getting very late at night where I am, so I''m too tired to elaborate, but I''m giving this 10!', '2003-02-02 14:23:48.000000', NULL, 1),
(205111, 11536, 1037, '<td valign="top">Wow, great curves and lovely high contrast black and white. I''ve scored a lot of photos high in this challenge, but this is another one I want to give a 10. It''s just so cool :).</td>', 'Wow, great curves and lovely high contrast black and white. I''ve scored a lot of photos high in this challenge, but this is another one I want to give a 10. It''s just so cool :).', '2003-02-02 14:24:56.000000', NULL, 1),
(205112, 11504, 1037, '<td valign="top">WOW! This is just.... amazing. If you set this up, your feeling for lighting and composition is amazing, but if you just got it by chance.... No, I can''t believe that. Great work. 10!</td>', 'WOW! This is just.... amazing. If you set this up, your feeling for lighting and composition is amazing, but if you just got it by chance.... No, I can''t believe that. Great work. 10!', '2003-02-02 14:26:26.000000', NULL, 1),
(205113, 11357, 1037, '<td valign="top">Haha. Wow, hairy foot! I wish I could comment further on this, but there''s not much to say.</td>', 'Haha. Wow, hairy foot! I wish I could comment further on this, but there''s not much to say.', '2003-02-02 14:28:07.000000', NULL, 1),
(205115, 11379, 1037, '<td valign="top">Oh dear. This is another photo that I find too beautiful to give anything lower than a 9. I''ve been too soft on this challenge! The colours and textures of this are really lovely, and that sweep of green vine just tops it off.</td>', 'Oh dear. This is another photo that I find too beautiful to give anything lower than a 9. I''ve been too soft on this challenge! The colours and textures of this are really lovely, and that sweep of green vine just tops it off.', '2003-02-02 14:29:37.000000', NULL, 1),
(205116, 11518, 1037, '<td valign="top">Interesting reflections. The composition is strong, but the photo overall seems a bit flat to me. The colours are nice though.</td>', 'Interesting reflections. The composition is strong, but the photo overall seems a bit flat to me. The colours are nice though.', '2003-02-02 14:31:08.000000', NULL, 1),
(205117, 11404, 1037, '<td valign="top">Hmmm.... stark and a bit awkwardly framed. It doesn''t grab me very much.</td>', 'Hmmm.... stark and a bit awkwardly framed. It doesn''t grab me very much.', '2003-02-02 14:31:54.000000', NULL, 1),
(205119, 11525, 1037, '<td valign="top">Cool photo. I like the framing and the pose your sister is in. It shows a lot of familiarity with her, and brings out her personality, as well as the rustic charm of the old building. Nice work.</td>', 'Cool photo. I like the framing and the pose your sister is in. It shows a lot of familiarity with her, and brings out her personality, as well as the rustic charm of the old building. Nice work.', '2003-02-02 14:35:36.000000', NULL, 1),
(205120, 11512, 1037, '<td valign="top">Busy and a bit softly focussed. The colours are washed out. The idea is interesting, but the photo doesn''t appeal to me.</td>', 'Busy and a bit softly focussed. The colours are washed out. The idea is interesting, but the photo doesn''t appeal to me.', '2003-02-02 14:37:02.000000', NULL, 1),
(205125, 11402, 1037, '<td valign="top">Wow... it''s weird when you take a photo from one angle and then rotate it. The distorted perspective has an odd effect.The subtle beauty of the colours and textures of this old building are a bit diminished by the artificially blue sky.</td>', 'Wow... it''s weird when you take a photo from one angle and then rotate it. The distorted perspective has an odd effect.The subtle beauty of the colours and textures of this old building are a bit diminished by the artificially blue sky.', '2003-02-02 14:38:43.000000', NULL, 1),
(205126, 11426, 1037, '<td valign="top">Weird, I already commented on this one but it came up again! I think I said that it was weird, and I like it :).</td>', 'Weird, I already commented on this one but it came up again! I think I said that it was weird, and I like it :).', '2003-02-02 14:39:24.000000', NULL, 1),
(205128, 11464, 1037, '<td valign="top">Cool colours. The composition is a little dull though.</td>', 'Cool colours. The composition is a little dull though.', '2003-02-02 14:40:21.000000', NULL, 1),
(205130, 11568, 1037, '<td valign="top">Lovely colours and textures. It''s a little blocky and flat in its composition... centred and square like that. But I like it.</td>', 'Lovely colours and textures. It''s a little blocky and flat in its composition... centred and square like that. But I like it.', '2003-02-02 14:42:13.000000', NULL, 1),
(205134, 11623, 1037, '<td valign="top">Interesting and weird. I like it.<br/> <br/>Edit - I gave that comment on a completely different photo, but it came up on this one!!!<br/> <br/>I like the colours on this photo, and the slight perspective gives the composition a lift. Nice work.</td>', 'Interesting and weird. I like it. Edit - I gave that comment on a completely different photo, but it came up on this one!!! I like the colours on this photo, and the slight perspective gives the composition a lift. Nice work.', '2003-02-02 14:44:34.000000', NULL, 1),
(205172, 11523, 1255, '<td valign="top">Great angle.  I like the lighting on the door anf the contrast between it and the bricks.</td>', 'Great angle.  I like the lighting on the door anf the contrast between it and the bricks.', '2003-02-02 16:17:35.000000', NULL, 1),
(205173, 11485, 1255, '<td valign="top">Seems a little too high contrast.  The darks are dark, the lights are light, and there is not too much in between.  I realize this may have been difficult to affect given the natual lighting and depending on your camera.</td>', 'Seems a little too high contrast.  The darks are dark, the lights are light, and there is not too much in between.  I realize this may have been difficult to affect given the natual lighting and depending on your camera.', '2003-02-02 16:19:17.000000', NULL, 1),
(205175, 11498, 1255, '<td valign="top">I like the blank reflection in the windows, it''s like vacant eyes staring out.  Also the graininess of the sky and the borders add to this shot for me.</td>', 'I like the blank reflection in the windows, it''s like vacant eyes staring out.  Also the graininess of the sky and the borders add to this shot for me.', '2003-02-02 16:22:00.000000', NULL, 1),
(205176, 11471, 1255, '<td valign="top">Very whimsical looking.  I like the twirls and the border.</td>', 'Very whimsical looking.  I like the twirls and the border.', '2003-02-02 16:25:32.000000', NULL, 1),
(205185, 11651, 4648, '<td valign="top">This is an absolutely beautiful sanctuary.  I hope the blue is the real color in this room.  It is such a soft, safe feeling, relaxing, peaceful shade of blue.  You can almost feel His presence in this photo.  This is a 10 and should be 1st.</td>', 'This is an absolutely beautiful sanctuary.  I hope the blue is the real color in this room.  It is such a soft, safe feeling, relaxing, peaceful shade of blue.  You can almost feel His presence in this photo.  This is a 10 and should be 1st.', '2003-02-02 16:43:21.000000', NULL, 1),
(205186, 11635, 4648, '<td valign="top">Two questions;  1)  what is the white spot in the corner of the bottom pane?  2)  why the angle of the window?  I love the tips of the bushes at the bottom of the window.  Blast those wiress.   Shame all utilities aren''t buried.  Nice choice of B &amp; W.</td>', 'Two questions;  1)  what is the white spot in the corner of the bottom pane?  2)  why the angle of the window?  I love the tips of the bushes at the bottom of the window.  Blast those wiress.   Shame all utilities aren''t buried.  Nice choice of B & W.', '2003-02-02 16:46:39.000000', NULL, 1),
(205187, 11379, 1280, '<td valign="top">This reminds me of my grandfather''s basement door, where he used to make red wine.  None of us kids were ever allowed in there.  Nice image!  Good color.</td>', 'This reminds me of my grandfather''s basement door, where he used to make red wine.  None of us kids were ever allowed in there.  Nice image!  Good color.', '2003-02-02 16:48:10.000000', NULL, 1),
(205189, 11648, 4648, '<td valign="top">Is this in Hell, Michigan?  Thought maybe it had frozen.  Beautiful ice cycles.  But your roof was dirty.  These aren''t any good for eating, just beautiful to look at.  The bird house or feeder is a nice touch.  Really like this photo.  The cropping, focus, colors, etc.  are all well done.  This is worth an 8 in my book.</td>', 'Is this in Hell, Michigan?  Thought maybe it had frozen.  Beautiful ice cycles.  But your roof was dirty.  These aren''t any good for eating, just beautiful to look at.  The bird house or feeder is a nice touch.  Really like this photo.  The cropping, focus, colors, etc.  are all well done.  This is worth an 8 in my book.', '2003-02-02 16:50:22.000000', NULL, 1),
(205191, 11559, 1280, '<td valign="top">Artsy...cool!</td>', 'Artsy...cool!', '2003-02-02 16:53:03.000000', NULL, 1),
(205192, 11496, 4648, '<td valign="top">I love the depth to this door.  Wish you hadn''t cropped off the very tip of the arch.  Otherwise it would have been a perfect photo.  Love the brickwork.  This is so neat of a photo, and well done, except for the arch. Still worth a 7 or 8</td>', 'I love the depth to this door.  Wish you hadn''t cropped off the very tip of the arch.  Otherwise it would have been a perfect photo.  Love the brickwork.  This is so neat of a photo, and well done, except for the arch. Still worth a 7 or 8', '2003-02-02 16:53:25.000000', NULL, 1),
(205194, 11586, 772, '<td valign="top">I really like the blue saturation in the sky on this shot.. the yellow of the mailbox really contrasts well with that blue also.  You caught an excellent combination of light and shadow with this shot.. nice work :) - setzler</td>', 'I really like the blue saturation in the sky on this shot.. the yellow of the mailbox really contrasts well with that blue also.  You caught an excellent combination of light and shadow with this shot.. nice work :) - setzler', '2003-02-02 16:54:29.000000', NULL, 1),
(205196, 11511, 772, '<td valign="top">excellent work with this shot... I like the way you have centered the door and clipped the windows at the top in this image.  It looks like a face :)  Nice work.. - setzler</td>', 'excellent work with this shot... I like the way you have centered the door and clipped the windows at the top in this image.  It looks like a face :)  Nice work.. - setzler', '2003-02-02 16:55:37.000000', NULL, 1),
(205197, 11383, 772, '<td valign="top">beautiful play of light and shadow on this image.  The sharp contrasts really create nice impact here... excellent work :) - setzler</td>', 'beautiful play of light and shadow on this image.  The sharp contrasts really create nice impact here... excellent work :) - setzler', '2003-02-02 16:56:49.000000', NULL, 1),
(205198, 11402, 4648, '<td valign="top">Love the angle looking up, but why the tilt?  Not sure I like that.  This is such a beautiful old church, it seem such a shame to ruin it by tilting the photo.  I love the stone work.  I just love the old building and the photo is beautiful, and well done - with that one exception.  That tilt hurts me.</td>', 'Love the angle looking up, but why the tilt?  Not sure I like that.  This is such a beautiful old church, it seem such a shame to ruin it by tilting the photo.  I love the stone work.  I just love the old building and the photo is beautiful, and well done - with that one exception.  That tilt hurts me.', '2003-02-02 16:57:29.000000', NULL, 1),
(205202, 11580, 4648, '<td valign="top">Is this building really black.  Beautiful archway.  Such beautiful workmanship, paying attention to every detail.  Personally I would have liked to see as much above the archway as you have below the doorway.  Still a nice photo.</td>', 'Is this building really black.  Beautiful archway.  Such beautiful workmanship, paying attention to every detail.  Personally I would have liked to see as much above the archway as you have below the doorway.  Still a nice photo.', '2003-02-02 17:02:09.000000', NULL, 1),
(205206, 11549, 4648, '<td valign="top">Beautiful craftmanship.  Wish this had been closer so we could see the details.  Not sure if this was supposed to be a black and white or what.  But I really like it.  Just a shame it wasn''t tighter on a window.  Well done.</td>', 'Beautiful craftmanship.  Wish this had been closer so we could see the details.  Not sure if this was supposed to be a black and white or what.  But I really like it.  Just a shame it wasn''t tighter on a window.  Well done.', '2003-02-02 17:05:21.000000', NULL, 1),
(205208, 11357, 772, '<td valign="top">Interesting alternative view of the challenge... subjectively, the photo lacks impact for me... maybe if you shaved first it would make a more appealing image :) - setzler</td>', 'Interesting alternative view of the challenge... subjectively, the photo lacks impact for me... maybe if you shaved first it would make a more appealing image :) - setzler', '2003-02-02 17:07:54.000000', NULL, 1),
(205209, 11443, 4648, '<td valign="top">Awesome.  Wish there was a ittle more light so we could see the details in the window, especially the top round part of it.  Wonder what the signifigance to this window is.  It''s beautiful.  And not many of these around anymore.  Lighten the photo just a little more and I personally would be thrilled.</td>', 'Awesome.  Wish there was a ittle more light so we could see the details in the window, especially the top round part of it.  Wonder what the signifigance to this window is.  It''s beautiful.  And not many of these around anymore.  Lighten the photo just a little more and I personally would be thrilled.', '2003-02-02 17:08:43.000000', NULL, 1),
(205210, 11458, 772, '<td valign="top">very interesting use of digital manipulation.  The cut of the puzzle piece is a little rough though.. .maybe cleaning that up a tad would help a bit :) - setzler</td>', 'very interesting use of digital manipulation.  The cut of the puzzle piece is a little rough though.. .maybe cleaning that up a tad would help a bit :) - setzler', '2003-02-02 17:08:58.000000', NULL, 1),
(205211, 11489, 4648, '<td valign="top">I love the wood on this old home.  Where is this place?  The wood is so beautifully weathered.  I would love to see the whole home.  This is so well done, it looks like I''m there in person.  Would make a wonderful painting.  Fantastic job.</td>', 'I love the wood on this old home.  Where is this place?  The wood is so beautifully weathered.  I would love to see the whole home.  This is so well done, it looks like I''m there in person.  Would make a wonderful painting.  Fantastic job.', '2003-02-02 17:11:32.000000', NULL, 1),
(205212, 11426, 772, '<td valign="top">I like the digital manipulation on this shot quite a bit.  The surrealism here adds nice impact to image.  The maniuplation is clean enough to make it look real :) - setzler</td>', 'I like the digital manipulation on this shot quite a bit.  The surrealism here adds nice impact to image.  The maniuplation is clean enough to make it look real :) - setzler', '2003-02-02 17:12:56.000000', NULL, 1),
(205213, 11453, 4648, '<td valign="top">Love the round towers on this home.  Also love the color of it.  The sky is beautiful.  Looks like everything was going your way this day.  Gone are these wonderful wrap around porches.  We need them back.  This photo could be used in an advertisment for this home or location.  Beautiful photo, well done.  It''s at least a 9</td>', 'Love the round towers on this home.  Also love the color of it.  The sky is beautiful.  Looks like everything was going your way this day.  Gone are these wonderful wrap around porches.  We need them back.  This photo could be used in an advertisment for this home or location.  Beautiful photo, well done.  It''s at least a 9', '2003-02-02 17:15:22.000000', NULL, 1),
(205215, 11639, 4648, '<td valign="top">Why the Locked heavy gate infront of a church?  The shadows are distracting and appear to be caused by two totally different things.  I really believe this photo is a sign of the times - when you have to lock a gate to Heaven''s gate.  There''s a story here, that needs to be written with this photo on the front cover.</td>', 'Why the Locked heavy gate infront of a church?  The shadows are distracting and appear to be caused by two totally different things.  I really believe this photo is a sign of the times - when you have to lock a gate to Heaven''s gate.  There''s a story here, that needs to be written with this photo on the front cover.', '2003-02-02 17:21:21.000000', NULL, 1),
(205216, 11622, 4648, '<td valign="top">Nice clear shot.  Good photo:  lighting right, focus good, cropping right on, meets challenge, especially good photo, well done</td>', 'Nice clear shot.  Good photo:  lighting right, focus good, cropping right on, meets challenge, especially good photo, well done', '2003-02-02 17:24:08.000000', NULL, 1),
(205217, 11559, 4648, '<td valign="top">Looks very strange in black and white.  The repairs to the steps jump out at you and give a strange appearance to the building.  Would have been better in color, in my opinion.  It almost looks like a drawing with some over-emphasis being made.</td>', 'Looks very strange in black and white.  The repairs to the steps jump out at you and give a strange appearance to the building.  Would have been better in color, in my opinion.  It almost looks like a drawing with some over-emphasis being made.', '2003-02-02 17:27:06.000000', NULL, 1),
(205220, 11525, 4648, '<td valign="top">Great old barn, but don''t think those 2 boards will hold much in. Love to have some of that wood to redo my family room inside.  Beautiful model in a beautiful photo.  Great job.</td>', 'Great old barn, but don''t think those 2 boards will hold much in. Love to have some of that wood to redo my family room inside.  Beautiful model in a beautiful photo.  Great job.', '2003-02-02 17:31:44.000000', NULL, 1),
(205222, 11483, 4648, '<td valign="top">Totally different take on this challenge.  You win for most unique.  I think every old house was painted this color at one time or another.  This photo stands out by itself and should place well up there.  Well done.</td>', 'Totally different take on this challenge.  You win for most unique.  I think every old house was painted this color at one time or another.  This photo stands out by itself and should place well up there.  Well done.', '2003-02-02 17:35:51.000000', NULL, 1),
(205223, 11474, 4648, '<td valign="top">This takes second place for creativity, only because you''ve really stretched it to fit the challenge.  But then I like imagination.  Why such a yellow paper?  Nice depth.  Good focus.  well done - even though it is quite a stretch.</td>', 'This takes second place for creativity, only because you''ve really stretched it to fit the challenge.  But then I like imagination.  Why such a yellow paper?  Nice depth.  Good focus.  well done - even though it is quite a stretch.', '2003-02-02 17:38:50.000000', NULL, 1),
(205225, 11461, 4648, '<td valign="top">Not sharp enough focus.  Beautiful otherwise.</td>', 'Not sharp enough focus.  Beautiful otherwise.', '2003-02-02 17:43:26.000000', NULL, 1),
(205226, 11488, 4648, '<td valign="top">This is so quaint.  I love the weathered boards.  Is this open to the public and where is it?  This is awesome and an awesome photo.  Beautiful photo.  Would have loved to seen the whole building.</td>', 'This is so quaint.  I love the weathered boards.  Is this open to the public and where is it?  This is awesome and an awesome photo.  Beautiful photo.  Would have loved to seen the whole building.', '2003-02-02 17:45:52.000000', NULL, 1),
(205227, 11618, 4648, '<td valign="top">Is this the House of David in Michigan with the bearded baseball team?  I have a postcard of them from about 50 years ago?  This is about what I would imagine their dairy barn looking like.  Great photo of a terribly rundown and dirty barn.  Like to know what the black is?  Maybe I don''t want to know.  Nice photo.  Lots of luck</td>', 'Is this the House of David in Michigan with the bearded baseball team?  I have a postcard of them from about 50 years ago?  This is about what I would imagine their dairy barn looking like.  Great photo of a terribly rundown and dirty barn.  Like to know what the black is?  Maybe I don''t want to know.  Nice photo.  Lots of luck', '2003-02-02 17:52:03.000000', NULL, 1),
(205228, 11523, 4648, '<td valign="top">Love this photo, especially the angle it is taken.  Beautiful job.  Shows the details of the weathered and warped door (left side as I look at it) and the stonework so clearly.  Great job.  Well done photo</td>', 'Love this photo, especially the angle it is taken.  Beautiful job.  Shows the details of the weathered and warped door (left side as I look at it) and the stonework so clearly.  Great job.  Well done photo', '2003-02-02 17:55:21.000000', NULL, 1),
(205260, 11498, 2553, '<td valign="top">I like the b &amp; w, the border, and the repetitive pattern of the windows, the cool architectural stuff at the top of the building, and the odd angle of your composition doesn''t even bother me too much.</td>', 'I like the b & w, the border, and the repetitive pattern of the windows, the cool architectural stuff at the top of the building, and the odd angle of your composition doesn''t even bother me too much.', '2003-02-02 19:53:18.000000', NULL, 1),
(205262, 11609, 4007, '<td valign="top">One of the examples of post shot processing that I really like this week. 8</td>', 'One of the examples of post shot processing that I really like this week. 8', '2003-02-02 20:04:55.000000', NULL, 1),
(205264, 11474, 2553, '<td valign="top">Gotta be honest- I''m not much on this "alternative" interpretation.  That aside; I like the sepia tone, and really like the blur, so that your circled areas really stand out.  I would have preferred to see newspaper throughout the photo - the area above the folded edge of the paper looks like it is not part of the paper, and I find it a little distracting. I like the way you composed the paper in the frame (at an angle like it''s laying on a table), I think a lot of people would have been tempted to take a straight-on shot (holding the paper up in front of the camera).</td>', 'Gotta be honest- I''m not much on this "alternative" interpretation.  That aside; I like the sepia tone, and really like the blur, so that your circled areas really stand out.  I would have preferred to see newspaper throughout the photo - the area above the folded edge of the paper looks like it is not part of the paper, and I find it a little distracting. I like the way you composed the paper in the frame (at an angle like it''s laying on a table), I think a lot of people would have been tempted to take a straight-on shot (holding the paper up in front of the camera).', '2003-02-02 20:06:15.000000', NULL, 1),
(205265, 11402, 4411, '<td valign="top">I love the angle you''ve used to get this in the frame, and the colour &amp; detail on the door and arch are fantastic, but I really don''t like the sky. It looks totally false and doesn''t fit the picture comfortably.</td>', 'I love the angle you''ve used to get this in the frame, and the colour & detail on the door and arch are fantastic, but I really don''t like the sky. It looks totally false and doesn''t fit the picture comfortably.', '2003-02-02 20:06:23.000000', NULL, 1),
(205266, 11629, 4411, '<td valign="top">Aww, so cute. I hope we get to see him/her again next week.</td>', 'Aww, so cute. I hope we get to see him/her again next week.', '2003-02-02 20:09:49.000000', NULL, 1),
(205267, 11454, 2553, '<td valign="top">VERY interesting shot!  Love the windows, and the fact that there is so much to look at.  I had to import this into PS so I could really check it out.  To be honest, I can''t tell what is manipulated, and what isn''t !  Love the nice warm tones with the bits of bright white interspersed throughout, and the repetition of the windows.  This is cool.</td>', 'VERY interesting shot!  Love the windows, and the fact that there is so much to look at.  I had to import this into PS so I could really check it out.  To be honest, I can''t tell what is manipulated, and what isn''t !  Love the nice warm tones with the bits of bright white interspersed throughout, and the repetition of the windows.  This is cool.', '2003-02-02 20:12:00.000000', NULL, 1),
(205268, 11468, 2553, '<td valign="top">Love the whole surreal look of this shot.  I like the nice warm skin tones against the cold blue of the window frame.  Probably my favorite thing about the shot is that it fades to black negative space at the top and the bottom, I really like that, and it seems to blend right into the missing puzzle pieces of the brick wall.</td>', 'Love the whole surreal look of this shot.  I like the nice warm skin tones against the cold blue of the window frame.  Probably my favorite thing about the shot is that it fades to black negative space at the top and the bottom, I really like that, and it seems to blend right into the missing puzzle pieces of the brick wall.', '2003-02-02 20:14:41.000000', NULL, 1),
(205269, 11491, 2553, '<td valign="top">Very cool work!  I would have preferred that the left side be as dark as the right side - I like the contrast and impact of the darker side better.</td>', 'Very cool work!  I would have preferred that the left side be as dark as the right side - I like the contrast and impact of the darker side better.', '2003-02-02 20:17:37.000000', NULL, 1),
(205270, 11364, 4007, '<td valign="top">great detail.  The placement of the iris in the frame seems unbalenced to me.  Perhaps having the iris centered or otherwise cropping just a little wider might help. 8</td>', 'great detail.  The placement of the iris in the frame seems unbalenced to me.  Perhaps having the iris centered or otherwise cropping just a little wider might help. 8', '2003-02-02 20:19:00.000000', NULL, 1),
