INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(205783, 11549, 6025, '<td valign="top">Critique Club<br/> <br/>The first thing that I noticed about this picture was the borders. They made me cringe violently for about 60 seconds. I must honestly say that I don''t particularly like border to begin with, but well. if you HAVE to use borders, I would suggest using a very thin black or white border (1 pixel, perhaps?) around the picture before adding coloured borders.<br/> <br/>When that whining is over width, I have to say I like your image. The crop on the left side leaves something to be desired, I feel, but overall the image is very good. Nice contrast, good sharpness and interesting composition.  The thingies on the window overhangs are very dtailed, and they make me kind of lose focus: I would think that the intention would be to pull the attention to the "wimpeltje" (whatever that is called in English) on the spire.<br/> <br/>I think, with the photo subject chosen, you could not have done a lot better. When that is said, I think I should probably say that I think you could have found more interesting subjects in that village.<br/> <br/>Personally, I gave you a 5, because I couldn''t quite make up my mind if I liked the image or not. strangely enough, I didn''t know why then, and I don''t really know why now. I''m sorry<br/> <br/>Haje</td>', 'Critique Club The first thing that I noticed about this picture was the borders. They made me cringe violently for about 60 seconds. I must honestly say that I don''t particularly like border to begin with, but well. if you HAVE to use borders, I would suggest using a very thin black or white border (1 pixel, perhaps?) around the picture before adding coloured borders. When that whining is over width, I have to say I like your image. The crop on the left side leaves something to be desired, I feel, but overall the image is very good. Nice contrast, good sharpness and interesting composition.  The thingies on the window overhangs are very dtailed, and they make me kind of lose focus: I would think that the intention would be to pull the attention to the "wimpeltje" (whatever that is called in English) on the spire. I think, with the photo subject chosen, you could not have done a lot better. When that is said, I think I should probably say that I think you could have found more interesting subjects in that village. Personally, I gave you a 5, because I couldn''t quite make up my mind if I liked the image or not. strangely enough, I didn''t know why then, and I don''t really know why now. I''m sorry Haje', '2003-02-03 07:43:23.000000', NULL, 0),
(205784, 11426, 472, '<td valign="top">inspired by MC Escher, but having to work with our extremely small cluttered living room, I did this pair of self-portraits and combined them in photoshop.  The icing on the cake for realism was photographing the doorknob from the correct angle separately and inserting it so that the door had some 3D qualities to it.  I figured, hey we may never have open editing again, so why not go for broke :)</td>', 'inspired by MC Escher, but having to work with our extremely small cluttered living room, I did this pair of self-portraits and combined them in photoshop.  The icing on the cake for realism was photographing the doorknob from the correct angle separately and inserting it so that the door had some 3D qualities to it.  I figured, hey we may never have open editing again, so why not go for broke :)', '2003-02-03 07:45:28.000000', NULL, 0),
(205820, 11363, 2716, '<td valign="top">Awesome framing.  Congrats on your ribbon.  Good job.</td>', 'Awesome framing.  Congrats on your ribbon.  Good job.', '2003-02-03 08:23:18.000000', NULL, 0),
